import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const Settings = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const [user, setUser] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [modalType, setModalType] = useState('');
    const [formData, setFormData] = useState({});

    // Fetch current user
    useEffect(() => {
        const fetchUser = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/auth/me', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setUser(res.data.user);
            } catch (err) {
                console.error("Error fetching user", err);
            }
        };
        fetchUser();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    const isActive = (path) => location.pathname === path;

    // Open Modal for specific setting
    const openModal = (type) => {
        setModalType(type);
        setFormData({});
        setShowModal(true);
    };

    // Close Modal
    const closeModal = () => {
        setShowModal(false);
        setModalType('');
        setFormData({});
    };

    // Handle form inputs
    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    // Submit changes
    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem('token');

            let updateData = {};
            if (modalType === 'name') {
                updateData = { firstName: formData.firstName, lastName: formData.lastName };
            } else if (modalType === 'password') {
                updateData = { password: formData.password };
            } else if (modalType === 'email') {
                updateData = { email: formData.email };
            } else if (modalType === 'phone') {
                updateData = { phone: formData.phone };
            } else if (modalType === 'language') {
                updateData = { language: formData.language };
            }

            await axios.put('http://localhost:5000/api/auth/update', updateData, {
                headers: { Authorization: `Bearer ${token}` }
            });

            alert("✅ Changes saved successfully!");
            closeModal();
            window.location.reload();
        } catch (err) {
            console.error("Error updating profile", err);
            alert("❌ Failed to update. Please try again.");
        }
    };

    return (
        <div className="settings-page">
            {/* ==================== NAVBAR ==================== */}
            <nav className="settings-navbar">
                <div className="nav-logo">BeautyBook</div>
                <div className="nav-links-desktop">
                    {/* Beauty treatments Link */}
                    <span className={`nav-item ${isActive('/services') ? 'active' : ''}`} onClick={() => navigate('/services')}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{marginRight: '6px'}}>
                            <path d="M12 2.69l5.19 5.2 7.48-1.65-2.17 8.59 7.41 4.2-5.19 5.2-7.48 1.65-4.2-7.41-7.41-4.2 2.17-8.59L12 2.69z"/>
                            <path d="M12 22V2"/>
                        </svg>
                        Beauty treatments
                    </span>

                    {/* Appointment Link */}
                    <span className={`nav-item ${isActive('/appointments') ? 'active' : ''}`} onClick={() => navigate('/appointments')}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{marginRight: '6px'}}>
                            <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                            <line x1="16" y1="2" x2="16" y2="6"></line>
                            <line x1="8" y1="2" x2="8" y2="6"></line>
                            <line x1="3" y1="10" x2="21" y2="10"></line>
                            <line x1="12" y1="14" x2="12" y2="18"></line>
                            <line x1="16" y1="14" x2="16" y2="18"></line>
                        </svg>
                        Appointment
                    </span>

                    {/* Notification Bell */}
                    <span className="nav-icon">
                        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path>
                            <path d="M13.73 21a2 2 0 0 1-3.46 0"></path>
                        </svg>
                    </span>

                    {/* Settings Gear (Navigate to Settings - Stays HERE) */}
                    <span className="nav-icon" onClick={() => navigate('/settings')} style={{cursor: 'pointer'}}>
                        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <circle cx="12" cy="12" r="3"></circle>
                            <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"></path>
                        </svg>
                    </span>
                </div>
            </nav>

            {/* ==================== SETTINGS CONTENT ==================== */}
            <div className="settings-content">
                <div className="settings-card">
                    {/* Profile Section */}
                    <div className="profile-section">
                        <div className="profile-avatar">
                            <svg width="60" height="60" viewBox="0 0 24 24" fill="none">
                                <circle cx="12" cy="12" r="12" fill="#dda0dd" />
                                <circle cx="12" cy="9" r="4" fill="#f4a460" />
                                <path d="M4 22c0-4.42 3.58-8 8-8s8 3.58 8 8" fill="#dda0dd" />
                                <circle cx="16" cy="10" r="2.5" fill="#87ceeb" />
                            </svg>
                        </div>
                        <h2 className="profile-name">{user?.firstName ? `${user.firstName} ${user.lastName}` : 'your name'}</h2>
                    </div>

                    {/* Settings Buttons */}
                    <div className="settings-buttons">
                        <button className="setting-btn" onClick={() => openModal('picture')}>change your picture</button>
                        <button className="setting-btn" onClick={() => openModal('deletePicture')}>Delete your picture</button>
                        <button className="setting-btn" onClick={() => openModal('name')}>change your name</button>
                        <button className="setting-btn" onClick={() => openModal('password')}>change your password</button>
                        <button className="setting-btn" onClick={() => openModal('language')}>change language</button>
                        <button className="setting-btn" onClick={() => openModal('emailPhone')}>change your email/phone</button>
                    </div>
                </div>
            </div>

            {/* ==================== MODAL ==================== */}
            {showModal && (
                <div className="settings-modal-overlay" onClick={closeModal}>
                    <div className="settings-modal" onClick={(e) => e.stopPropagation()}>
                        <h3>Update Settings</h3>
                        <form onSubmit={handleSubmit}>
                            {modalType === 'name' && (
                                <>
                                    <input type="text" name="firstName" placeholder="First Name" onChange={handleChange} required />
                                    <input type="text" name="lastName" placeholder="Last Name" onChange={handleChange} required />
                                </>
                            )}
                            {modalType === 'password' && (
                                <input type="password" name="password" placeholder="New Password" onChange={handleChange} required />
                            )}
                            {modalType === 'emailPhone' && (
                                <>
                                    <input type="email" name="email" placeholder="Email" onChange={handleChange} required />
                                    <input type="text" name="phone" placeholder="Phone" onChange={handleChange} required />
                                </>
                            )}
                            {modalType === 'language' && (
                                <select name="language" onChange={handleChange} required>
                                    <option value="fr">French</option>
                                    <option value="en">English</option>
                                    <option value="ar">Arabic</option>
                                </select>
                            )}
                            <div className="modal-actions">
                                <button type="button" className="cancel-modal-btn" onClick={closeModal}>Cancel</button>
                                <button type="submit" className="confirm-booking-btn">Save</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Settings;
